#!/usr/bin/env python3
"""Generate the straight-line derivatives of the softened potential."""
from pathlib import Path

P = 12
indices = [(x, y, n-x-y) for n in range(P+1)
           for x in range(n+1) for y in range(n-x+1)]
lookup = {a: i for i, a in enumerate(indices)}
out = [
    "// Generated by gen.py.",
    "template<int P> static inline void derivatives(V x, V y, V z, V* d) {",
    "  V r[3] = {x,y,z};",
    "  V q = x*x+y*y+z*z+splat(EPS2);",
    "  V iq = splat(1.0)/q;",
    "  d[0] = splat(1.0)/_mm256_sqrt_pd(q);",
]
for n in range(1, P+1):
    out.append(f"  if constexpr(P >= {n}) {{")
    for a in indices:
        if sum(a) != n:
            continue
        i = max(range(3), key=lambda j: a[j])
        g = list(a)
        g[i] -= 1
        terms = [f"splat({2*g[i]+1}.0)*r[{i}]*d[{lookup[tuple(g)]}]"]
        if g[i]:
            h = g.copy()
            h[i] -= 1
            terms.append(f"splat({g[i]*g[i]}.0)*d[{lookup[tuple(h)]}]")
        for j in range(3):
            if j == i or not g[j]:
                continue
            h = g.copy()
            h[j] -= 1
            h[i] += 1
            terms.append(f"splat({2*g[j]}.0)*r[{j}]*d[{lookup[tuple(h)]}]")
            if g[j] >= 2:
                h[j] -= 1
                terms.append(f"splat({g[j]*(g[j]-1)}.0)*d[{lookup[tuple(h)]}]")
        out.append(f"    d[{lookup[a]}] = -iq*({' + '.join(terms)});")
    out.append("  }")
out.append("}")
Path(__file__).with_name("derivatives.h").write_text("\n".join(out) + "\n")
